import type { Expression, FunctionDeclaration, Program, Statement } from "./ast.ts";

const typeNames: Record<string, string> = {
  i32: "int32_t",
  void: "void",
  bool: "bool",
  cstring: "const char *",
};

export function generateC(program: Program, sourceName: string): string {
  const functionTypes = new Map(program.functions.map((declaration) => [declaration.name, declaration.returnType.name]));
  const lines = [
    "/* Generated by the Z bootstrap compiler. */",
    `/* Source: ${sourceName.replaceAll("*/", "* /")} */`,
    "#include <stdbool.h>",
    "#include <stdint.h>",
  ];

  for (const declaration of program.imports) {
    lines.push(`#include <${declaration.header}>`);
  }
  lines.push("");

  for (const declaration of program.functions) {
    lines.push(generateFunction(declaration, functionTypes), "");
  }
  return `${lines.join("\n")}\n`;
}

function generateFunction(declaration: FunctionDeclaration, functionTypes: Map<string, string>): string {
  const storage = declaration.name === "main" ? "" : "static ";
  const returnType = mapType(declaration.returnType.name);
  const parameters = declaration.parameters.length === 0
    ? "void"
    : declaration.parameters.map((parameter) => `${mapType(parameter.type.name)} ${parameter.name}`).join(", ");
  const localTypes = new Map(declaration.parameters.map((parameter) => [parameter.name, parameter.type.name]));
  const body = declaration.body.map((statement) => {
    const generated = generateStatement(statement, localTypes, functionTypes);
    if (statement.kind === "variable") {
      const type = statement.type?.name ?? inferExpressionType(statement.initializer, localTypes, functionTypes);
      localTypes.set(statement.name, type);
    }
    return `  ${generated}`;
  }).join("\n");
  return `${storage}${returnType} ${declaration.name}(${parameters}) {\n${body}\n}`;
}

function generateStatement(
  statement: Statement,
  localTypes: Map<string, string>,
  functionTypes: Map<string, string>,
): string {
  switch (statement.kind) {
    case "variable": {
      const zType = statement.type?.name ?? inferExpressionType(statement.initializer, localTypes, functionTypes);
      const declaration = generateLocalDeclaration(zType, statement.name, statement.mutable);
      return `${declaration} = ${generateExpression(statement.initializer)};`;
    }
    case "return":
      return statement.expression ? `return ${generateExpression(statement.expression)};` : "return;";
    case "expressionStatement":
      return `${generateExpression(statement.expression)};`;
  }
}

function generateLocalDeclaration(type: string, name: string, mutable: boolean): string {
  if (type === "cstring") {
    return mutable ? `const char *${name}` : `const char * const ${name}`;
  }
  return `${mutable ? "" : "const "}${mapType(type)} ${name}`;
}

function inferExpressionType(
  expression: Expression,
  localTypes: Map<string, string>,
  functionTypes: Map<string, string>,
): string {
  switch (expression.kind) {
    case "number":
    case "binary":
      return "i32";
    case "string":
      return "cstring";
    case "identifier":
      return localTypes.get(expression.name) ?? "i32";
    case "call":
      return expression.callee.kind === "identifier"
        ? functionTypes.get(expression.callee.name) ?? "i32"
        : "i32";
    case "member":
      return "i32";
  }
}

function generateExpression(expression: Expression): string {
  switch (expression.kind) {
    case "number":
      return expression.value;
    case "string":
      return JSON.stringify(expression.value);
    case "identifier":
      return expression.name;
    case "binary":
      return `(${generateExpression(expression.left)} ${expression.operator} ${generateExpression(expression.right)})`;
    case "member":
      if (expression.object.kind === "identifier") {
        // Imported module namespaces disappear at the native C call boundary.
        return expression.property;
      }
      throw new Error("the bootstrap C backend only supports members on imported module names");
    case "call":
      return `${generateExpression(expression.callee)}(${expression.arguments.map(generateExpression).join(", ")})`;
  }
}

function mapType(name: string): string {
  const mapped = typeNames[name];
  if (!mapped) throw new Error(`unsupported bootstrap type ${JSON.stringify(name)}`);
  return mapped;
}
